import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o,af as t}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"阿里云百炼 Cookbook","description":"按场景抄：别混用 Key、挡住扣费、无代码问答、装百炼 CLI。不写灵码/千问完整教程。","frontmatter":{"title":"阿里云百炼 Cookbook","description":"按场景抄：别混用 Key、挡住扣费、无代码问答、装百炼 CLI。不写灵码/千问完整教程。","domain":"product","tags":["model-platform"],"role":"cookbook"},"headers":[],"relativePath":"zh/products/bailian/bailian-cookbook.md","filePath":"zh/products/bailian/bailian-cookbook.md","lastUpdated":1787107158000}'),l={name:"zh/products/bailian/bailian-cookbook.md"};function s(n,e,r,d,h,p){return o(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="阿里云百炼-cookbook" tabindex="-1">阿里云百炼 Cookbook <a class="header-anchor" href="#阿里云百炼-cookbook" aria-label="Permalink to &quot;阿里云百炼 Cookbook&quot;">​</a></h1><blockquote><p>已经会发第一条请求。这里按问题给步骤。基础开通见 <a href="./bailian.html">教程</a>。</p></blockquote><h2 id="把现有-openai-代码迁到百炼" tabindex="-1">把现有 OpenAI 代码迁到百炼 <a class="header-anchor" href="#把现有-openai-代码迁到百炼" aria-label="Permalink to &quot;把现有 OpenAI 代码迁到百炼&quot;">​</a></h2><p>官方口径：改 <strong>API Key、base_url、模型名称</strong>。<a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></p><ol><li><code>apiKey</code> 读 <code>process.env.DASHSCOPE_API_KEY</code>。</li><li><code>baseURL</code> 换成该地域的 OpenAI 兼容主机，并填入 <code>{WorkspaceId}</code>（北京 / 新加坡 / 东京 / 法兰克福）。美国弗吉尼亚以<a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">模型清单</a>为准。</li><li><code>model</code> 换成清单里的 ID。不要沿用 <code>gpt-4o</code> 这类名字。</li><li>流式、tools 是否可用，看该模型在清单页标注的协议，不要假设「兼容 = 全功能对等」。</li></ol><p>完整 Node / Python / curl 以<a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">首次调用</a>为准。</p><h2 id="不要把三套凭证混在一起" tabindex="-1">不要把三套凭证混在一起 <a class="header-anchor" href="#不要把三套凭证混在一起" aria-label="Permalink to &quot;不要把三套凭证混在一起&quot;">​</a></h2><p>这是扣费和 <code>invalid_api_key</code> 的第一来源。<a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a>、<a href="https://help.aliyun.com/zh/model-studio/token-plan-overview" target="_blank" rel="noreferrer">Token Plan</a></p><table tabindex="0"><thead><tr><th>计费方式</th><th>Key 长什么样</th><th>Base URL 认哪张纸</th></tr></thead><tbody><tr><td>按量付费</td><td><code>sk-</code> 或 <code>sk-ws</code></td><td><a href="https://help.aliyun.com/zh/model-studio/first-api-call-to-qwen" target="_blank" rel="noreferrer">首次调用</a> / <a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">模型清单</a> 的 OpenAI 或 Anthropic 主机</td></tr><tr><td>Coding Plan</td><td><code>sk-sp-</code>（套餐页）</td><td>OpenAI：<code>https://coding.dashscope.aliyuncs.com/v1</code>；Anthropic：<code>https://coding.dashscope.aliyuncs.com/apps/anthropic</code></td></tr><tr><td>Token Plan</td><td>套餐专属 Key（官方写 <code>sk-sp-</code> 前缀）</td><td><strong>以 Token Plan 控制台当时展示的 URL 为准</strong>，不要抄 Coding Plan 的主机</td></tr></tbody></table><p>官方点名的混用后果：</p><ul><li>通用 Key + 套餐 URL → <code>invalid_api_key</code>。</li><li>通用 Key + 按量 URL → <strong>不抵扣套餐，按量出账</strong>。</li><li>已买 Coding Plan 仍欠费：多半是工具里还留着 <code>sk-</code> 和 <code>dashscope.aliyuncs.com</code>。</li></ul><p>Coding Plan <strong>只允许编程工具</strong>（官方举例：Claude Code、Qoder、Qoder CN、OpenClaw）。用套餐 Key 打自己的后端、脚本、批量任务，官方视为违规，可能停订阅或封 Key。</p><p>Token Plan 要求工具支持 OpenAI 或 Anthropic 协议。界面长得像官方工具但不通标准 API 的，不能抵扣套餐，应改用按量 <code>sk-</code> / <code>sk-ws</code>。</p><p>把 Key 填进某个客户端时，只打开官方对应页，不要在本站复制逐步截图：</p><ul><li>总入口：<a href="https://help.aliyun.com/zh/model-studio/use-chat-client-or-development-tool/" target="_blank" rel="noreferrer">接入客户端/开发工具</a></li><li>例：<a href="https://help.aliyun.com/zh/model-studio/claude-code" target="_blank" rel="noreferrer">Claude Code</a>、<a href="https://help.aliyun.com/zh/model-studio/chatbox" target="_blank" rel="noreferrer">Chatbox</a>、<a href="https://help.aliyun.com/zh/model-studio/use-chat-client-or-development-tool/" target="_blank" rel="noreferrer">Cursor</a></li></ul><p>通义灵码 / Qoder CN 的完整 IDE 教程不在本目录，见 #84。这里只记一句：官方说个人社区版 / 个人专业版可接入百炼，<strong>企业版不支持</strong>。<a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">Qoder CN</a></p><h2 id="挡住新人额度耗尽后的按量账单" tabindex="-1">挡住新人额度耗尽后的按量账单 <a class="header-anchor" href="#挡住新人额度耗尽后的按量账单" aria-label="Permalink to &quot;挡住新人额度耗尽后的按量账单&quot;">​</a></h2><p>中国站规则见<a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免费额度</a>：</p><ol><li>额度只在<strong>北京</strong>，有效期 <strong>90 天</strong>，从开通、模型发布或申请通过之日取较晚者。</li><li>只抵扣<strong>实时推理</strong>。不抵扣 Batch、调优、部署、自定义模型。</li><li>每个模型（含带日期的快照）额度独立。官方写各模型「通常为 100 万 Token」——以控制台该模型详情为准，不要把营销页「超 7000 万」理解成一个池子。</li><li>已认证账号：控制台打开「<strong>免费额度用完即停</strong>」，耗尽返回 <code>AllocationQuota.FreeTierOnly</code>，不再转按量。</li><li>未认证账号：系统强制用完即停。</li><li>账户一旦欠费，其它模型即使还有免费额度也调不了。</li></ol><p>生产环境官方不建议开「用完即停」（额度耗尽服务会停）。生产用余额预警和删 Key。</p><p>Token Plan / Coding Plan 专属 Key <strong>不消耗</strong>这套新人免费额度。</p><h2 id="零代码做一个知识库问答" tabindex="-1">零代码做一个知识库问答 <a class="header-anchor" href="#零代码做一个知识库问答" aria-label="Permalink to &quot;零代码做一个知识库问答&quot;">​</a></h2><ol><li>打开控制台，确认地域。</li><li>按 <a href="https://help.aliyun.com/zh/model-studio/build-knowledge-base-qa-assistant-without-coding/" target="_blank" rel="noreferrer">0 代码构建问答应用</a> 建应用并挂知识库。</li><li>新项目优先 <a href="https://help.aliyun.com/zh/model-studio/new-single-agent-application" target="_blank" rel="noreferrer">Agent 2.0</a>。官方：无旧版依赖时推荐新版。1.0 和 2.0 <strong>不能互转</strong>。</li><li>发布后才能用 API / 渠道。未发布的草稿调不通。</li><li>知识库和模型推理<strong>分开计费</strong>。知识库不支持节省计划 / 资源包。<a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></li></ol><p>不要在这里展开调优、专属部署。那是另一条轴，官方入口：<a href="https://help.aliyun.com/zh/model-studio/model-training-overview" target="_blank" rel="noreferrer">模型调优</a>、<a href="https://help.aliyun.com/zh/model-studio/model-deployment-introduction" target="_blank" rel="noreferrer">模型部署</a>。</p><h2 id="安装百炼-cli" tabindex="-1">安装百炼 CLI <a class="header-anchor" href="#安装百炼-cli" aria-label="Permalink to &quot;安装百炼 CLI&quot;">​</a></h2><p>这是<strong>百炼自己的</strong>命令行（给 Agent 调多模态原子能力），不是阿里云 OpenAPI 的 <code>aliyun bailian</code>。</p><p>官方安装说明：<a href="https://bailian.aliyun.com/cli/install.md" target="_blank" rel="noreferrer">bailian.aliyun.com/cli/install.md</a></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Node.js ≥ 22.12.0，只用 npm 全局安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bailian-cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 本机浏览器登录（推荐）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --console</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 最小验证</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ping&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --non-interactive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>命令名是 <code>bl</code> 和 <code>bailian</code>。装 Skills 的官方命令是 <code>npx skills add modelstudioai/cli --all -g</code>。</p><p>无法弹浏览器时：<code>bl auth login --api-key &lt;用户粘贴的 Key&gt;</code>。不要把 Key 写进仓库或聊天记录。</p><p>全球地域开关官方写的是 <code>--region cn|us|intl</code>，默认 <code>cn</code>。</p>`,31)])])}const b=a(l,[["render",s]]);export{m as __pageData,b as default};
